from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import StopWatch, wait

# Set up.
prime_hub = PrimeHub()
LeftMotor = Motor(Port.E, Direction.COUNTERCLOCKWISE)
RightMotor = Motor(Port.A, Direction.CLOCKWISE)
driveBase = DriveBase(LeftMotor, RightMotor, 56, 4.375 * 25.4)
attachment = Motor(Port.B, Direction.CLOCKWISE)
color_sensor = ColorSensor(Port.C)
DriveToWallTimer = StopWatch()
speed = 1

def Drive_to_Wall(DriveSpeed, StopLoad, maxTime):
    DriveToWallTimer.reset()
    driveBase.drive(DriveSpeed, 0)
    while not (abs(LeftMotor.load()) >= StopLoad and abs(LeftMotor.load()) >= StopLoad or DriveToWallTimer.time() >= maxTime):
        wait(0)
    driveBase.brake()
    wait(50)

def TurnToLoad(MotorSpeed, ResetAngle, StopLoad):
    attachment.run(MotorSpeed)
    while not abs(attachment.load()) >= StopLoad:
        wait(0)
    attachment.brake()
    wait(250)
    attachment.run_angle(MotorSpeed, ResetAngle, Stop.BRAKE)


# The main program starts here.
driveBase.use_gyro(True)
print('Hello, Pybricks!')
# attachment can move
# 250 degrees max from bottom
Drive_to_Wall(300, 35, 5000)
attachment.run_angle(500, -245)
driveBase.straight(-500)
attachment.run_angle(500, 245, Stop.COAST)
